"""WAN-248 local page operations; external authorities are explicitly absent."""
S['V3IncidentParticipants'] = obj({'participants':arr(string())}, ['participants'])
S['V3IncidentCreateRequest']['properties']['participants'] = {'type':'array','maxItems':50,'items':string(minLength=1,maxLength=100)}
for _name in ('V3IncidentDetail','V3IncidentCaseDetail'):
    S[_name]['properties']['participants'] = arr(string())
v3_route('post','/incidents/{id}/participants','Append incident participant display names',
    body=obj({'names':{'type':'array','minItems':1,'maxItems':50,'items':string(minLength=1,maxLength=100)}},['names']),
    response=ref('V3IncidentParticipants'),desc='Appends and deduplicates at most 50 human display names under the incident lock. Names do not grant access. Requires current human session and both events change/view on the persisted incident application/environment. Success and failure audited; audit failure rolls back business writes.')
v3_route('put','/investigation-templates/{id}','Create a new bounded investigation template revision',
    body=obj({'expected_revision':integer(minimum=1),'name':string(minLength=1,maxLength=160),'budget':obj({'tools':integer(minimum=0,maximum=16),'minutes':integer(minimum=1,maximum=5)},['tools','minutes'])},['expected_revision','name','budget']),
    response=obj({'revision':integer(minimum=1),'template':ref('V3InvestigationTemplate')},['revision','template']),
    desc='Expected revision is the numeric version from the listed vN. Retains all other template fields and advances by one; ongoing starts retain their immutable snapshots. Requires current human canvas change and view authority. Stale revision returns409. This is local configuration, no model or upstream execution.')

S['V3MaintenancePlan'] = obj({**fieldnames('id schedule reason owner application_id environment_id'),'matchers':arr(string()),'status':string(enum=['planned'])},['id','schedule','matchers','reason','owner','application_id','environment_id','status'])
v3_route('get','/maintenance-windows','Read authorized local maintenance plans',response=obj({'items':arr(ref('V3MaintenancePlan')),'execution_enabled':v3_bool()},['items','execution_enabled']),desc='Local plans only, execution_enabled is always false. Current events view is checked per plan. No external silence exists merely because a plan was recorded. At most500 candidates; excess returns503 instead of incomplete totals.')
v3_route('post','/maintenance-windows','Register a local maintenance plan',body=obj({'schedule':string(minLength=1,maxLength=500),'matchers':{'type':'array','minItems':2,'maxItems':16,'items':string()},'reason':string(minLength=1,maxLength=2000)},['schedule','matchers','reason']),response=obj({'id':string(),'status':string(enum=['planned']),'execution_enabled':v3_bool()},['id','status','execution_enabled']),status=201,desc='User confirmed local plan only. Schedule is a human description, not parsed or automatically executed. Matchers are distinct exact key=value strings and must include application_id=<stable app ID> and environment=<selected key>. Requires human events change/view on that application/environment. No Alertmanager, cluster, model or notification call.')
v3_route('post','/assignments','Assign an operational item with durable inbox notification',body=obj({'item_kind':string(enum=['alert','incident','proposal']),'item_id':string(),'assignee':string(description='Stable active human user ID, never a display name')},['item_kind','item_id','assignee']),response=obj({'ok':v3_bool(),'notification':string(enum=['inbox'])},['ok','notification']),desc='User confirmed in-app notification only. Under target lock, recheck current human actor view/change and recipient environment/item view. Persists assignment and inbox notification with audit in one transaction; same assignee retry creates no second notice. Existing alert owner is updated; incident/proposal assignments use the independent assignment ledger. No approval/execution authority is conferred. GET inbox exposes only current assignments still visible to recipient. No external notification is sent.')
S['V3InboxItem']['properties']['kind']['enum'].append('assignment')
P['/inbox']['get']['description'] = P['/inbox']['get']['description'].replace('All and mine count only this bounded portion;', 'All and mine include this bounded alert portion and current durable assignment notices;')
P['/inbox']['get']['description'] += ' v1.1 also includes durable assignment notices for the current recipient, still rechecking current object/environment grants. Assignment ledger records are not read receipts. all_scope and mine_scope describe only the alert portion; assignment_scope identifies the additional current_assignment_notifications portion. Other non-alert event types remain unavailable.'

v3_route('get','/notification-deliveries','Read authorized platform delivery ledger',query=[v3_query('range',string(enum=['15m','30m','1h','6h','24h','7d','30d'])),v3_query('q')],response=obj({'items':arr(obj({**fieldnames('time alert receiver result')},['time','alert','receiver','result'])),'source':string(enum=['platform_delivery_ledger']),'receiver_kind':string(enum=['channel_id'])},['items','source','receiver_kind']),desc='Range actually limits created_at, default24h; literal q matches alert ID/channel/status. Current events view is rechecked per app/environment. Receiver is the registered channel ID, not a guessed person. result preserves pending/sending/retrying/sent/failed from the platform ledger; sent is transport acknowledgement, not human receipt. At most500 selected records; excess503.')
for _path,_code,_summary in [('/notification-templates','notification_templates_unavailable','Require a trusted notification template catalog'),('/oncall-schedules','oncall_schedules_unavailable','Require a trusted complete on-call schedule catalog')]:
    v3_route('get',_path,_summary,status=503,response=ref('Error'),desc='User-approved fail-closed boundary. Current alert_rules view and environment checks apply. No complete trusted catalog is configured; always503 '+_code+'. Does not derive fake templates or escalation schedules from route names/current-user evidence.')

v3_route('post','/me/contacts/{kind}/verification','Require a verified contact send-and-confirm authority',body=obj({'value':string(maxLength=254)},['value']),status=503,response=ref('Error'),desc='kind=email|phone. Validate plain email or E.164 phone, current human cookie session and selected environment. Always503 contact_verification_unavailable until trusted send-and-confirm authority exists. Never returns202 or mutates contacts without delivery proof. Rejection audited without contact values.')
v3_route('delete','/me/contacts/feishu','Require a trusted identity unlink and fallback authority',status=503,response=ref('Error'),desc='Current human cookie session and environment required. Always503 contact_unlink_unavailable until both authoritative unlink and verified fallback delivery exist. No local preference change masquerades as identity unbinding. Rejection audited.')
v3_route('put','/me/avatar','Store the current account private avatar',response=obj({'url':string()},['url']),desc='Exactly one multipart file named file. Decode actual PNG/JPEG: at most2MiB, minimum256x256; maximum4096 pixels per side limits image decoder memory. Stores original bytes with random revision, never client path. Current human cookie session/environment; business write and audit atomic. URL is private current-user authenticated content. GET me avatar_url retains the latest URL when complete profile evidence is available.')
P['/me/avatar']['put']['requestBody']={'required':True,'content':{'multipart/form-data':{'schema':obj({'file':string(format='binary')},['file'])}}}
v3_route('delete','/me/avatar','Delete the current account private avatar',status=204,desc='Current human session and one environment required. Idempotent delete with atomic audit. Old revision content URLs become404.')
v3_route('get','/me/avatar/content/{revision}','Read the current account private avatar revision',desc='Selected-environment header is optional for this personal content URL. Authenticated current human only; ownership derives from session, never path. Only latest revision is accessible. Private no-store, decoded PNG/JPEG content type, nosniff. Deleted, replaced and another account revision return404.')
P['/me/avatar/content/{revision}']['get']['responses']['200']['content']={'image/png':{'schema':string(format='binary')},'image/jpeg':{'schema':string(format='binary')}}
S['V3Me']['properties']['avatar_url']={'type':['string','null']}
P['/alert-groups']['get'].setdefault('parameters',[]).append(v3_query('group_by',string(enum=['service,alertname','service','alertname','cluster,namespace'])))
P['/alert-groups']['get']['description'] += ' Explicit group_by performs local display grouping from persisted labels with application/environment implicit boundaries. Missing requested label fails503. IDs begin viewgroup: and are not accepted by exact-source bulk actions/policy; actionable=false. Omitted group_by preserves previous exact-source grouping and IDs.'

S["V3InboxPartial"]["properties"]["assignment_scope"] = string(enum=["current_assignment_notifications"])
